from pipeline import transform

def test_public_policy_example():
    assert transform({'roster': {'people': ['a', 'b'], 'aliases': [], 'consents': [{'person': 'a', 'revision': 1, 'allowed': True}, {'person': 'b', 'revision': 1, 'allowed': True}]}, 'prior': [{'id': 'published', 'epoch': 'current', 'members': ['a', 'b'], 'count': 1}], 'packages': [{'id': 'pool', 'queries': [{'id': 'pool-count', 'members': ['a', 'b']}], 'utility': 3, 'approved': True}], 'policy': {'max_changes': 0, 'protected': ['a', 'b'], 'minimum_utility': 3}, 'snapshots': {'old': {'a': 1, 'b': 0}, 'current': {'a': 1, 'b': 0}}}) == {'ready': True, 'baseline_safe': True, 'baseline_candidate_count': 2, 'policy': [{'world': 1, 'package': 'pool'}, {'world': 2, 'package': 'pool'}], 'total_utility': 6, 'guaranteed_utility': 3, 'publication': {'package': 'pool', 'counts': [{'id': 'pool-count', 'count': 1}], 'utility': 3}, 'candidate_count': 2, 'protected_count': 2, 'ambiguous_protected_count': 2, 'excluded_packages': [], 'blocker_codes': []}
